673	        const key = product.itemId ?? product.id;
674	        // when showInventoryMessage is true, it means child product is not orderable
675	        // Deviation from the base file: optional call. The prop has no default, and the base
676	        // calls it unguarded — only reachable for set/bundle children, whose parent always
677	        // supplies it.
678	        setChildProductOrderability?.((previousState) => ({
679	          ...previousState,
