702	
703	    const renderDefaultVariationAttribute = (attr: SfccVariationAttribute) => {
704	      const { id, name, selectedValue, values } = attr;
705	      const swatches = values.map(({ href, name, image, value, orderable }: SfccVariationValue, index: number) => {
706	        // audit-allow: verbatim from base product-view (index.jsx:689); copy-first requires it unchanged
707	        const content = image ? (
708	          <Box
