716	          />
717	        ) : (
718	          name
719	        );
720	        const hasSelection = Boolean(selectedValue?.value);
721	        const isSelected = selectedValue?.value === value;
722	        const isFirst = index === 0;
723	        // To mimic the behavior of a native radio input, only
724	        // one swatch should receive tab focus; the rest can be
725	        // selected using arrow keys when the swatch group has
726	        // focus. The focused element is the selected option or
727	        // the first in the group, if no option is selected.
728	        // This is a slight difference, for simplicity, from the
