730	        // `Tab` and the _last_ element is focused on `Shift+Tab`
731	        const isFocusable = isSelected || (!hasSelection && isFirst);
732	        return (
733	          <Swatch
734	            key={value}
735	            href={href}
736	            disabled={!orderable}
737	            value={value}
