765	
766	    return (
767	      <Flex direction={'column'} data-testid="product-view" ref={ref}>
768	        {/* Basic information etc. title, price, breadcrumb*/}
769	        <Box display={['block', 'block', 'block', 'none']}>
770	          {renderHeader({
771	            name: product?.name,
772	            product,
773	            priceData,
774	            currency: product?.currency || activeCurrency,
775	            category,
776	            isProductPartOfBundle,
777	          })}
778	        </Box>
779	        <Flex direction={['column', 'column', 'column', 'row']}>
780	          {showImageGallery && (
781	            <Box flex={1} mr={[0, 0, 0, 6, 6]}>
782	              {product ? (
783	                <>
784	                  <ImageGallery
