799	                <ImageGallerySkeleton />
800	              )}
801	              {/* Custom footer content (e.g., Back to Selection button) */}
802	              {imageGalleryFooter && (
803	                <Box mt={6} mb={2}>
804	                  {imageGalleryFooter}
805	                </Box>
806	              )}
807	            </Box>
808	          )}
809	
810	          {/* Variations & Quantity Selector & CTA buttons */}
811	          {/* audit-allow: verbatim from base product-view (index.jsx:636-638); copy-first requires it unchanged */}
812	          <VStack
813	            align="stretch"
814	            spacing={8}
815	            flex={1}
816	            pb={[
817	              isProductPartOfSet || isProductPartOfBundle ? 4 : '120px',
818	              isProductPartOfSet || isProductPartOfBundle ? 4 : '120px',
819	              isProductPartOfSet || isProductPartOfBundle ? 4 : '120px',
820	              4,
821	            ]}
822	          >
823	            <Box display={['none', 'none', 'none', 'block']}>
824	              {renderHeader({
825	                name: product?.name,
826	                product,
827	                priceData,
828	                currency: product?.currency || activeCurrency,
829	                category,
830	                isProductPartOfBundle,
831	              })}
832	            </Box>
833	            <VStack align="stretch" spacing={4}>
834	              {isProductPartOfBundle && (
835	                <Box>
836	                  <Text fontWeight="medium" fontSize="md" aria-label="price">
837	                    <label>
838	                      {intl.formatMessage({
839	                        defaultMessage: 'Quantity',
840	                        id: 'product_view.label.quantity',
841	                      })}
842	                      : {childOfBundleQuantity}
843	                    </label>
844	                  </Text>
845	                </Box>
846	              )}
847	              {/*
848	                                Customize the skeletons shown for attributes to suit your needs. At the point
849	                                that we show the skeleton we do not know how many variations are selectable. So choose
850	                                a a skeleton that will meet most of your needs.
851	                            */}
852	              {showLoading ? (
853	                <>
854	                  {/* First Attribute Skeleton */}
855	                  <Skeleton height={6} width={32} />
856	                  <Skeleton height={20} width={64} />
857	
858	                  {/* Second Attribute Skeleton */}
859	                  <Skeleton height={6} width={32} />
860	                  <Skeleton height={20} width={64} />
861	                </>
862	              ) : (
863	                variationAttributes.map((attr: SfccVariationAttribute) => (
864	                  <React.Fragment key={attr.id}>
865	                    {renderVariationAttribute?.(attr) ?? renderDefaultVariationAttribute(attr)}
866	                  </React.Fragment>
867	                ))
868	              )}
869	
870	              {/* audit-allow: verbatim from base product-view (index.jsx:754); copy-first requires it unchanged */}
871	              {!isProductASet && !isProductPartOfBundle && (
872	                <VStack align="stretch" maxWidth={'200px'}>
873	                  <Box fontWeight="bold">
874	                    <label htmlFor="quantity">
875	                      {intl.formatMessage({
876	                        defaultMessage: 'Quantity:',
877	                        id: 'product_view.label.quantity',
878	                      })}
879	                    </label>
880	                  </Box>
881	
882	                  <QuantityPicker
883	                    id="quantity"
884	                    step={stepQuantity}
885	                    value={quantity}
886	                    min={minOrderQuantity}
887	                    {...(maxOrderQuantity != null && { max: maxOrderQuantity })}
888	                    onChange={(stringValue: string, numberValue: number) => {
889	                      // Set the Quantity of product to value of input if value number
890	                      if (numberValue >= 0) {
891	                        setQuantity(numberValue);
892	                        if (isProductABundle) setSelectedBundleQuantity(numberValue);
893	                      } else if (stringValue === '') {
894	                        // We want to allow the use to clear the input to start a new input so here we set the quantity to '' so NAN is not displayed
895	                        // User will not be able to add '' qauntity to the cart due to the add to cart button enablement rules
896	                        setQuantity(stringValue);
897	                      }
898	                    }}
899	                    onBlur={(e: React.FocusEvent<HTMLInputElement>) => {
900	                      // Default to 1the `minOrderQuantity` if a user leaves the box with an invalid value
901	                      const value = e.target.value;
