907	                    onFocus={(e: React.FocusEvent<HTMLInputElement>) => {
908	                      // This is useful for mobile devices, this allows the user to pop open the keyboard and set the
909	                      // new quantity with one click. NOTE: This is something that can be refactored into the parent
910	                      // component, potentially as a prop called `selectInputOnFocus`.
911	                      e.target.select();
912	                    }}
913	                    productName={product?.name}
914	                  />
915	                </VStack>
916	              )}
917	              <Box ref={errorContainerRef}>
918	                {!showLoading && showOptionsMessage && (
919	                  <Fade in={true}>
920	                    <Text color="orange.600" fontWeight={600} marginBottom={8}>
921	                      {intl.formatMessage({
922	                        defaultMessage: 'Please select all your options above',
923	                      })}
924	                    </Text>
925	                  </Fade>
926	                )}
927	              </Box>
928	              <HideOnDesktop>
929	                {showFullLink && product && (
930	                  <Link to={`/product/${product.master.masterId}`} color="blue.600">
931	                    <FormattedMessage id="product_view.link.full_details" defaultMessage="See full details" />
932	                  </Link>
933	                )}
934	              </HideOnDesktop>
935	              {isProductASet && <p>{product?.shortDescription}</p>}
936	            </VStack>
937	
938	            <Box>
939	              {!showLoading && showInventoryMessage && !customInventoryMessage && (
940	                <Fade in={true}>
941	                  <Text color="orange.600" fontWeight={600} marginBottom={8}>
942	                    {inventoryMessage}
943	                  </Text>
944	                </Fade>
945	              )}
946	              {!showLoading && customInventoryMessage && (
947	                <Fade in={true}>
948	                  <Text color="orange.600" fontWeight={600} marginBottom={8}>
949	                    {customInventoryMessage}
950	                  </Text>
951	                </Fade>
952	              )}
953	              <Box>
954	                {showDeliveryOptions && (
955	                  <>
956	                    <Box mb={4}>
957	                      <Text fontWeight={600} mb={3}>
958	                        <FormattedMessage defaultMessage="Delivery:" id="product_view.label.delivery" />
959	                      </Text>
960	                      <RadioGroup
961	                        value={pickupInStore ? DELIVERY_OPTIONS.PICKUP : DELIVERY_OPTIONS.DELIVERY}
962	                        onChange={handleDeliveryOptionChange}
963	                        mb={1}
964	                      >
965	                        <Stack direction="column" spacing={2}>
966	                          <Radio value={DELIVERY_OPTIONS.DELIVERY} isDisabled={disableButton}>
967	                            <FormattedMessage
968	                              defaultMessage="Ship to Address"
969	                              id="product_view.label.ship_to_address"
970	                            />
971	                          </Radio>
972	                          {storeLocatorEnabled && (
973	                            <Radio
974	                              value={DELIVERY_OPTIONS.PICKUP}
975	                              isDisabled={!pickupEnabled || (storeName && inventoryId && isSelectedStoreOutOfStock)}
976	                            >
977	                              <FormattedMessage
978	                                defaultMessage="Pick Up in Store"
979	                                id="product_view.label.pickup_in_store"
980	                              />
981	                            </Radio>
982	                          )}
983	                        </Stack>
984	                      </RadioGroup>
985	                    </Box>
986	
987	                    {storeLocatorEnabled && (
988	                      <>
989	                        {storeName && inventoryId && (
990	                          <Text color="black" fontWeight={600} mb={2} data-testid="store-stock-status-msg">
991	                            {!isSelectedStoreOutOfStock
992	                              ? intl.formatMessage(
993	                                  {
994	                                    id: 'product_view.status.in_stock_at_store',
995	                                    defaultMessage: 'In stock at {storeName}',
996	                                  },
997	                                  {
998	                                    storeName: (
999	                                      <Link
1000	                                        as="button"
1001	                                        color="blue.600"
1002	                                        textDecoration="underline"
1003	                                        onClick={onOpenStoreLocator}
1004	                                      >
1005	                                        {storeName}
1006	                                      </Link>
1007	                                    ),
1008	                                  },
1009	                                )
1010	                              : intl.formatMessage(
1011	                                  {
1012	                                    id: 'product_view.status.out_of_stock_at_store',
1013	                                    defaultMessage: 'Out of Stock at {storeName}',
1014	                                  },
1015	                                  {
1016	                                    storeName: (
1017	                                      <Link
1018	                                        as="button"
1019	                                        color="blue.600"
1020	                                        textDecoration="underline"
1021	                                        onClick={onOpenStoreLocator}
1022	                                      >
1023	                                        {storeName}
1024	                                      </Link>
1025	                                    ),
1026	                                  },
1027	                                )}
1028	                          </Text>
1029	                        )}
1030	
1031	                        {/* Show label if pickup is disabled due to no store/inventoryId */}
1032	                        {!pickupEnabled && !storeName && !inventoryId && (
1033	                          <Text color="black" fontWeight={600} mb={3} data-testid="pickup-select-store-msg">
1034	                            <FormattedMessage
1035	                              defaultMessage="Pick up in "
1036	                              id="product_view.label.pickup_in_select_store_prefix"
1037	                            />{' '}
1038	                            <Link as="button" color="blue.600" textDecoration="underline" onClick={onOpenStoreLocator}>
1039	                              <FormattedMessage
1040	                                defaultMessage="Select Store"
1041	                                id="product_view.label.select_store_link"
1042	                              />
1043	                            </Link>
1044	                          </Text>
1045	                        )}
1046	                      </>
1047	                    )}
1048	                  </>
1049	                )}
1050	                <Box display={isProductPartOfSet ? 'block' : ['none', 'none', 'none', 'block']}>
1051	                  {renderActionButtons()}
1052	                </Box>
1053	              </Box>
1054	            </Box>
1055	          </VStack>
1056	        </Flex>
1057	
1058	        {/* Sticky call-to-action buttons for mobile and certain product types */}
1059	        <Box
1060	          position="fixed"
1061	          bg="white"
1062	          width="100%"
1063	          display={isProductPartOfSet || isProductPartOfBundle ? 'none' : ['block', 'block', 'block', 'none']}
1064	          p={[4, 4, 6]}
1065	          left={0}
1066	          bottom={0}
1067	          zIndex={2}
1068	          boxShadow={theme.shadows.top}
1069	        >
1070	          {renderActionButtons()}
1071	        </Box>
1072	
1073	        {/* Loading overlay during express payment confirmation */}
1074	        {confirmingBasket && <LoadingSpinner wrapperStyles={{ height: '100vh' }} />}
1075	      </Flex>
1076	    );
1077	  },
1078	);
1079	
1080	ProductView.displayName = 'ProductView';
1081	
1082	/*
1083	 * The base file's `ProductViewHeader.propTypes` / `ProductView.propTypes` blocks are not
1084	 * carried over: the `ProductViewHeaderProps` / `ProductViewProps` types above express the
1085	 * same prop contract, and do so at compile time for every caller rather than as a dev-only
1086	 * runtime warning. Keeping both would duplicate the contract in two places that can drift.
1087	 */
1088	
1089	export default ProductView;
