11	  title: 'Commerce/ZimmColourSwatch',
12	  component: ZimmColourSwatch,
13	  argTypes: {
14	    name: { control: 'text' },
15	    imageUrl: { control: 'text' },
16	    href: { control: 'text' },
17	    isSelected: { control: 'boolean' },
18	    isFocusable: { control: 'boolean' },
19	  },
20	  decorators: [
21	    // .storybook/preview.tsx (Tier 1) supplies Chakra + Intl globally but no Router — this atom
22	    // can render a react-router `Link`, which throws outside one. Local decorator, same reason
23	    // staticProductHeader.stories.tsx adds one for its own base-`Breadcrumb` links.
24	    (Story: React.ComponentType) => (
25	      <MemoryRouter>
26	        <Story />
27	      </MemoryRouter>
28	    ),
29	  ],
30	};
31	export default meta;
32	
33	type Story = StoryObj<typeof ZimmColourSwatch>;
34	
35	export const Default: Story = {
36	  args: {
37	    name: 'Bay Blue',
38	    imageUrl: SAMPLE_IMAGE_URL,
39	    href: '/womens/dresses/natura-mini-dress/8637DS241.html?color=BAYBL',
40	    isSelected: false,
41	    isFocusable: true,
42	  },
43	  play: async ({ canvasElement }) => {
44	    const canvas = within(canvasElement);
45	    const swatch = canvas.getByRole('radio', { name: 'Bay Blue' });
46	    await expect(swatch).toHaveAttribute('aria-checked', 'false');
47	    await expect(swatch.tagName).toBe('A');
48	    await expect(swatch).toHaveAttribute('href', '/womens/dresses/natura-mini-dress/8637DS241.html?color=BAYBL');
49	  },
50	};
51	
52	export const Selected: Story = {
53	  args: {
