68	    href: undefined,
69	    isSelected: false,
70	    isFocusable: true,
71	  },
72	  play: async ({ canvasElement }) => {
73	    const canvas = within(canvasElement);
74	    const swatch = canvas.getByRole('radio', { name: 'Ivory' });
75	    // No `href` means no anchor at all — a plain chakra.span instead.
76	    await expect(swatch.tagName).not.toBe('A');
77	  },
78	};
